    fun getPageForSurah(surah: Int): Int {
        val clamped = surah.coerceIn(1, 114)
        return surahStartPages[clamped - 1]
    }

    fun getPageForAyah(surah: Int, ayah: Int): Int {
        val s = surah.coerceIn(1, 114)
        val a = ayah.coerceAtLeast(1)
        for (i in 0 until TOTAL_PAGES) {
            val offset = i * 6
            val page = pageBoundaries[offset]
            val sStart = pageBoundaries[offset + 2]
            val aStart = pageBoundaries[offset + 3]
            val sEnd = pageBoundaries[offset + 4]
            val aEnd = pageBoundaries[offset + 5]
            val afterStart = (s > sStart) || (s == sStart && a >= aStart)
            val beforeEnd = (s < sEnd) || (s == sEnd && a <= aEnd)
            if (afterStart && beforeEnd) {
                return page
            }
        }
        return 1
    }

    fun getPageMeta(pageNumber: Int): PageMeta {
        val page = pageNumber.coerceIn(1, TOTAL_PAGES)
        val offset = (page - 1) * 6
        val juz = pageBoundaries[offset + 1]
        val sStart = pageBoundaries[offset + 2]
        val aStart = pageBoundaries[offset + 3]
        val sEnd = pageBoundaries[offset + 4]
        val aEnd = pageBoundaries[offset + 5]
        val surahMeta = QuranData.surahs.find { it.number == sStart }
        val surahName = surahMeta?.nameLatin ?: "Surat "
        val arabicName = surahMeta?.nameArabic ?: ""
        val ayahRangeText = if (sStart == sEnd) {
            if (aStart == aEnd) "Ayat " else "Ayat  - "
        } else {
            val endSurahMeta = QuranData.surahs.find { it.number == sEnd }
            val endSurahName = endSurahMeta?.nameLatin ?: "Surat "
            ":  - : "
        }
        return PageMeta(
            pageNumber = page,
            juz = juz,
            surahName = surahName,
            surahNumber = sStart,
            arabicSurahName = arabicName,
            ayahRangeText = ayahRangeText,
            startAyah = aStart,
            endAyah = aEnd
        )
    }

    fun getFirstAyahOnPage(pageNumber: Int): Pair<Int, Int> {
        val page = pageNumber.coerceIn(1, TOTAL_PAGES)
        val offset = (page - 1) * 6
        val sStart = pageBoundaries[offset + 2]
        val aStart = pageBoundaries[offset + 3]
        return Pair(sStart, aStart)
    }
}
